local _, addon = ...

addon.SoundChoices = {
    {key = "raid", label = "Raid warning", kit = "RAID_WARNING"},
    {key = "whisper", label = "Whisper", kit = "TELL_MESSAGE"},
    {key = "click", label = "Soft UI click", kit = "IG_MAINMENU_OPTION"},
}
table.insert(addon.SoundChoices, {key = "chime", label = "Gentle chime",
    file = "Interface\\AddOns\\PallySealCooldowns\\Sounds\\RefreshChime.wav"})
-- Bundled original sounds, generated by scripts/make_alert_sounds.py.
for _, sound in ipairs({
    {"doublechime", "Double chime", "DoubleChime"},
    {"bell", "Bright bell", "BrightBell"},
    {"glass", "Glass ping", "GlassPing"},
    {"arpeggio", "Rising arpeggio", "RisingArpeggio"},
    {"shimmer", "Holy shimmer", "HolyShimmer"},
    {"harp", "Harp pluck", "HarpPluck"},
    {"gong", "Soft gong", "SoftGong"},
    {"woodblock", "Wood block", "WoodBlock"},
    {"bubble", "Bubble pop", "BubblePop"},
    {"beeps", "Urgent beeps", "UrgentBeeps"},
}) do
    table.insert(addon.SoundChoices, {key = sound[1], label = sound[2],
        file = "Interface\\AddOns\\PallySealCooldowns\\Sounds\\" .. sound[3] .. ".wav"})
end
table.insert(addon.SoundChoices, {key = "readycheck", label = "Ready check", kit = "READY_CHECK"})
table.insert(addon.SoundChoices, {key = "alarm", label = "Alarm clock", kit = "ALARM_CLOCK_WARNING_3"})
table.insert(addon.SoundChoices, {key = "meow", label = "Cat meow",
    file = "Interface\\AddOns\\PallySealCooldowns\\Sounds\\CatMeow.wav"})
addon.SoundChannels = {"Master", "SFX", "Dialog"}

-- Each alert's default, also used when its chosen sound cannot play.
addon.SoundDefaults = {refresh = "chime", missing = "raid"}

-- Built-in sounds followed by any installed SharedMedia sounds.
function addon.SoundOptions()
    return addon.MediaChoices("sound", addon.SoundChoices)
end

function addon.IsValidSoundChoice(key)
    if type(key) ~= "string" then return false end
    if key:sub(1, 6) == "media:" then return #key > 6 and not addon.IsSilentMedia("sound", key) end
    for _, choice in ipairs(addon.SoundChoices) do
        if choice.key == key then return true end
    end
    return false
end

-- Returns true when the choice could be started.
local function PlayChoice(key, channel)
    if type(key) ~= "string" then return false end
    if key:sub(1, 6) == "media:" then
        local path = addon.MediaPath("sound", key)
        return path ~= nil and PlaySoundFile ~= nil and PlaySoundFile(path, channel) and true or false
    end
    for _, choice in ipairs(addon.SoundChoices) do
        if choice.key == key then
            if choice.file then
                return PlaySoundFile ~= nil and PlaySoundFile(choice.file, channel) and true or false
            end
            local kit = SOUNDKIT[choice.kit]
            if kit then PlaySound(kit, channel) end
            return kit ~= nil
        end
    end
    return false
end

function addon.PlayWarning(db, alert)
    local selected = alert == "missing" and db.missingSoundChoice or db.soundChoice
    if PlayChoice(selected, db.soundChannel) then return end
    local fallback = addon.SoundDefaults[alert == "missing" and "missing" or "refresh"]
    if selected ~= fallback and PlayChoice(fallback, db.soundChannel) then return end
    PlaySound(SOUNDKIT.RAID_WARNING, db.soundChannel)
end

addon.SettingsPages = {
    {key = "general", label = "General", height = 360},
    {key = "layout", label = "Layout", height = 490},
    {key = "alerts", label = "Alerts", height = 700},
    {key = "appearance", label = "Appearance", height = 520},
    {key = "presets", label = "Presets", height = 140},
}

function addon.CreateSettings(db, apply)
    local panelName = "PallySealCooldownsSettings"
    local panel = CreateFrame("Frame", panelName, UIParent, "BackdropTemplate")
    panel.name = "Pally Seal Cooldowns"
    panel:SetSize(440, 640)
    panel:SetPoint("CENTER")
    panel:SetClampedToScreen(true)
    panel:EnableMouse(true)
    panel:RegisterForDrag("LeftButton")
    panel:SetScript("OnDragStart", function(self)
        if not self.embedded then self:StartMoving() end
    end)
    panel:SetScript("OnDragStop", panel.StopMovingOrSizing)
    local title = panel:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
    title:SetPoint("TOPLEFT", 20, -20)
    title:SetText(panel.name)
    local close = CreateFrame("Button", nil, panel, "UIPanelCloseButton")
    close:SetPoint("TOPRIGHT", -4, -4)
    close:SetScript("OnClick", function() panel:Hide() end)
    function panel:SetEmbedded(embedded)
        self.embedded = embedded
        self:SetMovable(not embedded)
        self:SetFrameStrata(embedded and "MEDIUM" or "DIALOG")
        close:SetShown(not embedded)
        self:SetBackdrop(not embedded and {
            bgFile = "Interface\\DialogFrame\\UI-DialogBox-Background",
            edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
            tile = true, tileSize = 16, edgeSize = 16,
        } or nil)
        if not embedded then self:SetBackdropColor(0.08, 0.08, 0.12, 0.98) end
    end
    panel:SetEmbedded(false)

    -- Every change can alter which settings apply, so relayout after it.
    local applySettings = apply
    apply = function()
        applySettings()
        panel:Relayout()
    end
    local syncing = false
    local controls = {}
    local pages, tabs, selected = {}, {}, "general"
    panel.pages = pages
    for index, info in ipairs(addon.SettingsPages) do
        -- General is the category's own page; the rest become sub-pages.
        local page = CreateFrame("Frame", nil, index == 1 and panel or UIParent)
        page.key, page.name, page.height = info.key, info.label, info.height
        local heading = page:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
        heading:SetPoint("TOPLEFT", 20, -20)
        heading:SetText(info.label)
        local scroll = CreateFrame("ScrollFrame", nil, page, "UIPanelScrollFrameTemplate")
        scroll:SetPoint("TOPLEFT", 8, -50)
        scroll:SetPoint("BOTTOMRIGHT", -32, 16)
        page.content = CreateFrame("Frame", nil, scroll)
        page.content:SetSize(380, info.height)
        scroll:SetScrollChild(page.content)
        page.OnRefresh = function() panel:Synchronize() end
        page.refresh = page.OnRefresh
        if index > 1 then
            page:SetScript("OnShow", function(self)
                local parent = self:GetParent()
                if parent and parent ~= panel then self:SetFrameStrata(parent:GetFrameStrata()) end
                panel:Synchronize()
                apply()
            end)
            page:Hide()
        end
        pages[index], pages[info.key] = page, page
    end

    local function SelectPage(key)
        selected = key
        for _, page in ipairs(pages) do page:SetShown(page.key == key) end
        for _, tab in ipairs(tabs) do tab:SetEnabled(tab.key ~= key) end
    end
    for index, page in ipairs(pages) do
        local tab = CreateFrame("Button", nil, panel, "UIPanelButtonTemplate")
        tab.key = page.key
        tab:SetSize(80, 22)
        tab:SetPoint("TOPLEFT", 14 + (index - 1) * 82, -46)
        tab:SetText(page.name)
        tab:SetScript("OnClick", function() SelectPage(page.key) end)
        tabs[index] = tab
    end
    -- Hosted pages switch with tabs inside this frame (standalone window, or a
    -- client without sub-categories); otherwise each page is its own category.
    function panel:SetHostedPages(hosted)
        self.hosted = hosted
        title:SetShown(hosted)
        for _, tab in ipairs(tabs) do tab:SetShown(hosted) end
        for index, page in ipairs(pages) do
            if hosted or index == 1 then
                page:SetParent(self)
                page:ClearAllPoints()
                page:SetPoint("TOPLEFT", 0, hosted and -70 or 0)
                page:SetPoint("BOTTOMRIGHT")
            end
        end
        if hosted then
            SelectPage(selected)
        else
            for index, page in ipairs(pages) do page:SetShown(index == 1) end
        end
    end

    -- Rows register in page order. Rows whose condition fails are hidden and
    -- the rows below move up, so each page lists only settings that apply.
    local section
    local rows = {}
    local function Row(top, y, frames, place)
        local row = {page = section, top = top, y = y, frames = frames, place = place}
        rows[#rows + 1] = row
        return row
    end
    local function When(row, test)
        row.when = test
        return row
    end
    local function Style() return db.displayStyle end
    local function IsSwing() return db.displayStyle == "swing" end

    local function Checkbox(label, y, key, checkedValue, uncheckedValue)
        local button = CreateFrame("CheckButton", nil, section, "UICheckButtonTemplate")
        button:SetPoint("TOPLEFT", 18, y)
        local text = button:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
        text:SetPoint("LEFT", button, "RIGHT", 3, 0)
        text:SetText(label)
        button:SetScript("OnClick", function(self)
            db[key] = self:GetChecked() and checkedValue or uncheckedValue
            apply()
        end)
        controls[#controls + 1] = function() button:SetChecked(db[key] == checkedValue) end
        return Row(y, y, {button}, function(at)
            button:ClearAllPoints()
            button:SetPoint("TOPLEFT", 18, at)
        end)
    end

    -- A label may be a function so it can name what it sizes in each layout.
    local function Slider(label, y, key, minimum, maximum, step, format)
        local function Label() return type(label) == "function" and label() or label end
        local slider = CreateFrame("Slider", nil, section)
        slider:SetPoint("TOPLEFT", 26, y)
        slider:SetSize(330, 16)
        slider:SetOrientation("HORIZONTAL")
        slider:SetMinMaxValues(minimum, maximum)
        slider:SetValueStep(step)
        slider:SetObeyStepOnDrag(true)
        slider:SetThumbTexture("Interface\\Buttons\\UI-SliderBar-Button-Horizontal")
        local track = slider:CreateTexture(nil, "BACKGROUND")
        track:SetAllPoints()
        track:SetColorTexture(0.2, 0.2, 0.25, 1)
        local text = slider:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
        text:SetPoint("BOTTOMLEFT", slider, "TOPLEFT", 0, 6)
        slider:SetScript("OnValueChanged", function(_, value)
            local rounded = math.floor(value / step + 0.5) * step
            if (key == "timerSize" or key == "nameSize")
                and rounded > 0 and rounded < 8 then rounded = 0 end
            if key == "cdmIconSize" and rounded > 0 and rounded < 16 then rounded = 0 end
            text:SetText(Label() .. string.format(format, rounded))
            if syncing then return end
            db[key] = rounded
            addon.NormalizeAppearance(db)
            addon.NormalizeCooldownManager(db)
            apply()
        end)
        controls[#controls + 1] = function()
            slider:SetValue(db[key])
            text:SetText(Label() .. string.format(format, db[key]))
        end
        -- The label sits above the slider, so the row starts 25 px higher.
        return Row(y + 25, y, {slider}, function(at)
            slider:ClearAllPoints()
            slider:SetPoint("TOPLEFT", 26, at)
        end)
    end

    -- Choices use Blizzard's native dropdown (as Questie and Bagnon do on this
    -- client); clients without the template keep left/right-click cycling.
    local useDropdowns = DoesTemplateExist and DoesTemplateExist("WowStyle1DropdownTemplate") or false
    panel.usesDropdowns = useDropdowns
    local function Selector(label, y, key, source, onSelect)
        local function Choices()
            return type(source) == "function" and source() or source
        end
        local function Unavailable()
            return tostring(db[key]):gsub("^media:", "") .. " (unavailable)"
        end
        local function Choose(value)
            db[key] = value
            apply()
        end
        if useDropdowns then
            local dropdown = CreateFrame("DropdownButton", nil, section, "WowStyle1DropdownTemplate")
            dropdown:SetPoint("TOPLEFT", 150, y)
            dropdown:SetWidth(206)
            local text = dropdown:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
            text:SetPoint("LEFT", section, "TOPLEFT", 26, y - 13)
            text:SetText(label)
            dropdown:SetupMenu(function(_, root)
                if root.SetScrollMode then root:SetScrollMode(300) end
                for _, choice in ipairs(Choices()) do
                    -- Only a deliberate pick previews; cycling buttons stay silent.
                    root:CreateRadio(choice.label, function() return db[key] == choice.key end, function()
                        Choose(choice.key)
                        if onSelect then onSelect() end
                    end, choice.key)
                end
            end)
            controls[#controls + 1] = function()
                if dropdown.SetDefaultText then dropdown:SetDefaultText(Unavailable()) end
                dropdown:GenerateMenu()
            end
            local page = section
            return Row(y, y, {dropdown}, function(at)
                dropdown:ClearAllPoints()
                dropdown:SetPoint("TOPLEFT", 150, at)
                text:ClearAllPoints()
                text:SetPoint("LEFT", page, "TOPLEFT", 26, at - 13)
            end)
        end
        local button = CreateFrame("Button", nil, section, "UIPanelButtonTemplate")
        button:SetPoint("TOPLEFT", 26, y)
        button:SetSize(330, 26)
        button:RegisterForClicks("LeftButtonUp", "RightButtonUp")
        local function Update()
            local choices = Choices()
            button:SetText(label .. Unavailable())
            for _, choice in ipairs(choices) do
                if choice.key == db[key] then button:SetText(label .. choice.label .. "  >") end
            end
        end
        button:SetScript("OnClick", function(_, mouseButton)
            local choices = Choices()
            local selected = 0
            for index, choice in ipairs(choices) do
                if choice.key == db[key] then
                    selected = index
                    break
                end
            end
            local direction = mouseButton == "RightButton" and -1 or 1
            Choose(choices[(selected - 1 + direction) % #choices + 1].key)
            Update()
        end)
        controls[#controls + 1] = Update
        return Row(y, y, {button}, function(at)
            button:ClearAllPoints()
            button:SetPoint("TOPLEFT", 26, at)
        end)
    end

    local function ActionButton(label, y, width, onClick)
        local button = CreateFrame("Button", nil, section, "UIPanelButtonTemplate")
        button:SetSize(width, 26)
        button:SetPoint("TOPLEFT", 26, y)
        button:SetText(label)
        button:SetScript("OnClick", onClick)
        return Row(y, y, {button}, function(at)
            button:ClearAllPoints()
            button:SetPoint("TOPLEFT", 26, at)
        end)
    end

    local function Hint(y, text)
        local hint = section:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
        hint:SetPoint("TOPLEFT", 26, y)
        hint:SetWidth(330)
        hint:SetJustifyH("LEFT")
        hint:SetText(text)
        local row = Row(y, y, {hint}, function(at)
            hint:ClearAllPoints()
            hint:SetPoint("TOPLEFT", 26, at)
        end)
        row.region = hint
        return row
    end

    local function Heading(y, text)
        local heading = section:CreateFontString(nil, "OVERLAY", "GameFontNormal")
        heading:SetPoint("TOPLEFT", 22, y)
        heading:SetText(text)
        local row = Row(y, y, {heading}, function(at)
            heading:ClearAllPoints()
            heading:SetPoint("TOPLEFT", 22, at)
        end)
        row.region = heading
        return row
    end

    section = pages.general.content
    Checkbox("Lock tracker position", -10, "locked", true, false)
    Checkbox("Show countdown only when refresh is due", -45, "counterMode", "refresh", "always")
    Checkbox("Hide outside combat", -80, "hideOutOfCombat", true, false)
    -- The swing bar shows the fixed "Seal Timer" title instead.
    When(Checkbox("Show seal name", -115, "showSealName", true, false), function() return not IsSwing() end)
    Checkbox("Show status text", -150, "showStatusText", true, false)
    Slider("Refresh warning: ", -220, "threshold", 1, 30, 1, "%d seconds")
    Slider("Display size: ", -275, "scale", 0.5, 2, 0.05, "%.2fx")
    ActionButton("Reset position and size", -310, 170, function()
        db.x, db.y, db.scale = 0, -160, 1
        apply()
        panel:Synchronize()
    end)

    -- Only the chosen layout's options appear, under a heading naming it.
    section = pages.layout.content
    Selector("Layout: ", -10, "displayStyle", addon.LayoutChoices)
    Hint(-45, "Large icon: 52 px icon with a thin bar beneath.\n"
        .. "Small icon with timer bar: 30 px icon and a long bar.\n"
        .. "Essential Cooldowns icon: matches and attaches to Blizzard's bar.\n"
        .. "Swing timer bar: matches Forever's main-hand swing timer.")
    local layoutHeading = Heading(-115, "Layout options")
    local function IconLayout() return Style() == "icon" or Style() == "essential" end
    local function Essential() return Style() == "essential" end
    local function BarLayout() return Style() == "bar" or IsSwing() end
    -- Texture and countdown also style the thin bar under an icon layout.
    local function HasBar() return BarLayout() or db.showIconBar ~= false end
    When(Checkbox("Show duration bar under icon", -133, "showIconBar", true, false), IconLayout)
    When(Slider("Essential icon size: ", -195, "cdmIconSize", 0, 80, 1, "%d px (0 follows Blizzard)"), Essential)
    -- The Essential Cooldowns icon always snaps to Blizzard's bar; these place it.
    When(Selector("Snap position: ", -220, "snapSide", addon.SnapSides), Essential)
    When(Slider("Gap from bar: ", -275, "snapGap", 0, 20, 1, "%d px"), Essential)
    When(Hint(-302, "The icon attaches to Blizzard's Essential Cooldowns bar,\n"
        .. "follows it in Edit Mode, and cannot be dragged. If the bar\n"
        .. "is unavailable, the saved position is used."), Essential)
    When(Slider("Bar width: ", -375, "barWidth", 120, 360, 1, "%d px"), BarLayout)
    When(Selector("Bar texture: ", -410, "statusbar", function() return addon.MediaChoices("statusbar") end),
        HasBar)
    When(Checkbox("Bar counts down (starts full, drains right to left)", -445, "barCountdown", true, false),
        HasBar)

    section = pages.alerts.content
    Heading(-10, "Refresh warning")
    Checkbox("Play refresh warning sound", -28, "sound", true, false)
    Checkbox("Refresh sound only in combat", -63, "refreshCombatOnly", true, false)
    Selector("Refresh sound: ", -103, "soundChoice", addon.SoundOptions, function() addon.PlayWarning(db) end)
    local channels = {}
    for _, channel in ipairs(addon.SoundChannels) do
        channels[#channels + 1] = {key = channel, label = channel}
    end
    Selector("Audio channel: ", -138, "soundChannel", channels)
    ActionButton("Test refresh sound", -173, 170, function() addon.PlayWarning(db) end)
    Heading(-218, "When no seal is active")
    Selector("Combat alert: ", -238, "missingAlert", addon.MissingAlertChoices)
    Checkbox("Hide tracker when no seal is active", -270, "hideWhenMissing", true, false)
    Checkbox("Show missing-seal text", -305, "showMissingText", true, false)
    Selector("Missing symbol: ", -343, "missingSymbol", addon.MissingSymbols)
    -- The swing bar has no icon to stand in for.
    When(Selector("Placeholder icon: ", -378, "missingIcon", addon.MissingIcons),
        function() return not IsSwing() end)
    Checkbox("Play missing-seal sound", -410, "missingSound", true, false)
    -- The native display can only confirm a missing seal outside combat.
    When(Checkbox("Missing sound only in combat", -445, "missingCombatOnly", true, false),
        function() return not addon.NativeDisplayActive end)
    Selector("Missing sound: ", -485, "missingSoundChoice", addon.SoundOptions,
        function() addon.PlayWarning(db, "missing") end)
    ActionButton("Test missing sound", -520, 170, function() addon.PlayWarning(db, "missing") end)
    local alertsHint = Hint(-560, "")

    section = pages.appearance.content
    Hint(-10, (useDropdowns and "Changes apply live." or "Changes apply live. Left/right-click choices to cycle.")
        .. "\nFont size 0 uses the layout default.")
    Selector("Font: ", -48, "font", function() return addon.MediaChoices("font") end)
    Selector("Outline: ", -83, "outline", addon.OutlineChoices)
    Checkbox("Text shadow", -113, "fontShadow", true, false)
    Slider("Countdown font size: ", -178, "timerSize", 0, 40, 1, "%d px")
    Slider(function() return IsSwing() and "Label font size: " or "Seal name font size: " end,
        -233, "nameSize", 0, 24, 1, "%d px")
    Selector("Border: ", -268, "border", function() return addon.MediaChoices("border") end)
    -- The swing frame is Blizzard's art: Border only turns it on or off.
    When(Selector("Border color: ", -303, "borderColor", addon.BorderColors),
        function() return not IsSwing() and db.border ~= "none" end)
    When(Slider("Custom border thickness: ", -368, "borderSize", 1, 16, 1, "%d px"),
        function() return not IsSwing() and db.border ~= "none" and db.border ~= "default" end)
    Selector("Warning color: ", -403, "warningColor", addon.WarningColors)
    Hint(-440, "Installed SharedMedia choices appear automatically.\nMissing media uses the default appearance.\n"
        .. "Warning color marks a due refresh and a missing seal.\nBar options are on the Layout page.\n"
        .. "Only options for the chosen layout are shown.")

    section = pages.presets.content
    local presetHint = Hint(-10, "")
    local presetButtons = {}
    for _, choice in ipairs(addon.PresetChoices) do
        local preset = CreateFrame("Button", nil, section, "UIPanelButtonTemplate")
        preset:SetSize(106, 26)
        preset:SetText(choice.label)
        preset:SetScript("OnClick", function()
            addon.ApplyPreset(db, choice.key)
            apply()
            panel:Synchronize()
        end)
        presetButtons[#presetButtons + 1] = {button = preset, choice = choice}
    end

    -- Shows the rows that apply to the chosen layout and closes the gaps.
    function panel:Relayout()
        local swing = IsSwing()
        for _, page in ipairs(pages) do
            local offset, pageRows = 0, {}
            for _, row in ipairs(rows) do
                if row.page == page.content then pageRows[#pageRows + 1] = row end
            end
            for index, row in ipairs(pageRows) do
                local shown = not row.when or row.when() == true
                for _, region in ipairs(row.frames) do region:SetShown(shown) end
                if shown then
                    row.place(row.y + offset)
                else
                    local nextRow = pageRows[index + 1]
                    offset = offset + (nextRow and row.top - nextRow.top or 0)
                end
            end
            page.content:SetHeight(page.height - offset)
        end
        for _, choice in ipairs(addon.LayoutChoices) do
            if choice.key == db.displayStyle then layoutHeading.region:SetText(choice.label .. " options") end
        end
        alertsHint.region:SetText((addon.NativeDisplayActive
                and "The missing sound plays once outside combat after a\nseal ends, including one lost during combat.\n" or "")
            .. "Both alerts share the audio channel. Installed\nSharedMedia sounds appear after the built-in ones.\n"
            .. "Choosing a sound plays it. Tests play even when\nalerts are off or combat-only.\n"
            .. "Missing-seal text also follows Show seal name and\nShow status text on the General page.")
        presetHint.region:SetText("Presets replace only appearance settings.\n"
            .. "Timing, sounds, position, and visibility are kept."
            .. (swing and "\nOn the swing timer bar they change only text styling;\nthe bar keeps Blizzard's art." or ""))
        -- Presets that suit the layout fill the grid in order.
        local shownPresets = {}
        for _, choice in ipairs(addon.PresetChoicesFor(db)) do shownPresets[choice.key] = true end
        local index = 0
        for _, entry in ipairs(presetButtons) do
            local shown = shownPresets[entry.choice.key] == true
            entry.button:SetShown(shown)
            if shown then
                local column, row = index % 3, math.floor(index / 3)
                entry.button:ClearAllPoints()
                entry.button:SetPoint("TOPLEFT", 26 + column * 112, (swing and -64 or -50) - row * 34)
                index = index + 1
            end
        end
    end

    function panel:Synchronize()
        syncing = true
        for _, update in ipairs(controls) do update() end
        syncing = false
        self:Relayout()
    end
    panel.OnRefresh = function() panel:Synchronize() end
    panel.refresh = panel.OnRefresh
    panel:SetScript("OnShow", function(self)
        if self.embedded then
            self:SetFrameStrata(self:GetParent():GetFrameStrata())
        end
        self:Synchronize()
        apply()
    end)
    panel:SetHostedPages(true)
    panel:Hide()
    return panel
end

local settingsPanel, category, registered

function addon.RegisterSettings(db, apply)
    if registered or (InCombatLockdown and InCombatLockdown()) then return end
    local modern = Settings and type(Settings.RegisterCanvasLayoutCategory) == "function"
        and type(Settings.RegisterAddOnCategory) == "function"
    if not modern and type(InterfaceOptions_AddCategory) ~= "function" then return end
    if not settingsPanel then settingsPanel = addon.CreateSettings(db, apply) end
    settingsPanel:SetEmbedded(true)
    settingsPanel:ClearAllPoints()
    local pages = settingsPanel.pages
    if modern then
        category = Settings.RegisterCanvasLayoutCategory(settingsPanel, settingsPanel.name)
        Settings.RegisterAddOnCategory(category)
        local nested = type(Settings.RegisterCanvasLayoutSubcategory) == "function"
        if nested then
            for index = 2, #pages do
                Settings.RegisterCanvasLayoutSubcategory(category, pages[index], pages[index].name)
            end
        end
        settingsPanel:SetHostedPages(not nested)
    else
        InterfaceOptions_AddCategory(settingsPanel)
        for index = 2, #pages do
            pages[index].parent = settingsPanel.name
            InterfaceOptions_AddCategory(pages[index])
        end
        settingsPanel:SetHostedPages(false)
    end
    registered = true
end

function addon.OpenSettings(db, apply)
    if InCombatLockdown and InCombatLockdown() then
        DEFAULT_CHAT_FRAME:AddMessage("Pally Seals: Open settings after combat ends.")
        return
    end
    addon.RegisterSettings(db, apply)
    if category and Settings and type(Settings.OpenToCategory) == "function" then
        Settings.OpenToCategory(category:GetID())
    elseif registered and type(InterfaceOptionsFrame_OpenToCategory) == "function" then
        InterfaceOptionsFrame_OpenToCategory(settingsPanel)
    elseif not registered then
        if not settingsPanel then
            settingsPanel = addon.CreateSettings(db, apply)
            table.insert(UISpecialFrames, "PallySealCooldownsSettings")
        end
        settingsPanel:Show()
        settingsPanel:Synchronize()
    end
end
